export const DECISION_VARIANTS=Object.freeze({});

export const REDUNDANT_VARIANTS=Object.freeze({
  'hang:un-bras-assistee':'Même mécanique que « une main assistée »; seule la quantité d’aide est implicite.',
  'dip:volume':'Même technique que les dips stricts; seule la prescription change.',
  'dip:entretien':'Même technique que les dips stricts; seule la prescription change.',
  'bridge:entretien':'Même technique que le pont une jambe; seule la prescription change.',
  'calf:entretien-unilateral':'Même technique que la variante de base; seule la prescription change.'
});

export const CORRECTED_VARIANTS=new Set(Object.keys(VARIANT_TECHNIQUE_OVERRIDES));

export function variantAuditStatus(exerciseId,variantId){
  const key=`${exerciseId}:${variantId}`;
  if(DECISION_VARIANTS[key])return'DECISION_REQUIRED';
  if(REDUNDANT_VARIANTS[key])return'REDUNDANT';
  if(CORRECTED_VARIANTS.has(key))return'CORRECTED';
  return'OK';
}

export function mergeTechnique(base,override={}){
  return{...base,...override,startPosition:override.startPosition||base.startPosition,grip:override.grip===undefined?base.grip:override.grip};
}
